package org.chromium.chrome.browser.profiles; import java.util.*; public class ProfileManager { public interface Observer {void onProfileAdded(Profile p);void onProfileDestroyed(Profile p);} static List<Observer> observers=new ArrayList<>();public static int count(){return observers.size();}public static void addObserver(Observer o){observers.add(o);}public static void destroy(Profile p){p.alive=false;for(Observer o:observers)o.onProfileDestroyed(p);} }
